SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, AVG(shipping_fee) OVER (PARTITION BY store_id, customer_id ORDER BY shipping_fee, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) shipping_fee_avg_2_prior, LAG(shipping_fee, 1) OVER (PARTITION BY channel, store_id ORDER BY discount, id) prev_shipping_fee, ROW_NUMBER() OVER (ORDER BY amount DESC, id) seq_no, NTILE(5) OVER (ORDER BY discount DESC, id) discount_bucket FROM orders
